/* @lc app=leetcode id=4027 lang=kotlin */ class Solution { fun elevatorRequests(n: Int, start: Int, requests: Array<IntArray>): Long = requests.size.let { m -> Array(1 shl m) { LongArray(m) { Long.MAX_VALUE / 4 } }.also { f -> (0 until m).forEach { j -> f[1 shl j][j] = maxOf(Math.abs(start - requests[j][1]).toLong(), requests[j][0].toLong()) } }.also { f -> (1 until (1 shl m)).forEach { mask -> (0 until m).filter { mask shr it and 1 == 1 && f[mask][it] < Long.MAX_VALUE / 8 }.forEach { l -> (0 until m).filter { mask shr it and 1 == 0 }.forEach { j -> f[mask or (1 shl j)].let { row -> row[j] = minOf(row[j], maxOf(f[mask][l] + Math.abs(requests[l][1] - requests[j][1]), requests[j][0].toLong())) } } } } }.let { f -> f[(1 shl m) - 1].min() } } }